// Included by the existing isolated MariaDB integration fixture.
void StorageSql(CAsyncSQL& admin,CAsyncSQL& writer,const ItemCatalog& c){
    const ItemOwner actor{ItemOwnerKind::Character,880133},alt{ItemOwnerKind::Character,880134},recipient{ItemOwnerKind::Character,880135},account{ItemOwnerKind::Account,880333},otherAccount{ItemOwnerKind::Account,880334},guild{ItemOwnerKind::Guild,880335};
    Execute(admin,"INSERT INTO player.player(id,name,account_id) VALUES(880133,'StorageA',880333),(880134,'StorageB',880333),(880135,'StorageC',880334)");Execute(admin,"INSERT INTO player.guild VALUES(880335,880133)");Execute(admin,"INSERT INTO player.guild_member VALUES(880133,880335,1),(880134,880335,15)");
    for(const auto o:{actor,alt,recipient,account,otherAccount,guild})Check(p::EnsureRuntimeStorageOwner(writer,c,o).has_value(),"runtime storage bootstrap");auto initial=p::LoadCurrentItemOwner(writer,c,account).value();Check(initial.fence.sessionGeneration==1 && initial.wallets[0].balance==0,"new typed account wallet starts once, without importing legacy currency");Check(p::EnsureRuntimeStorageOwner(writer,c,account).has_value() && p::LoadCurrentItemOwner(writer,c,account)->fence==initial.fence,"repeated bootstrap preserves shared generation and revision");
    // Authorization adds a variable number of SQL guards before the owner rows.
    // Exercise the runtime read path, including every guard shape.
    StorageActor reader{880133,880333,880335,{120,0,0},true,true,true,true};
    for(const auto route:{StorageRoute::Bank,StorageRoute::Mall,StorageRoute::Guild,StorageRoute::Mail,StorageRoute::Awards,StorageRoute::Wallet}){
        const StorageAuthorization auth{reader,{route,StorageCommand::Withdraw}};
        for(const auto o:{actor,account})Check(p::LoadAuthorizedStorageOwner(writer,c,o,0,auth).has_value(),"authenticated storage snapshot read");
        if(route==StorageRoute::Guild)Check(p::LoadAuthorizedStorageOwner(writer,c,guild,0,auth).has_value(),"authenticated guild snapshot read");
    }
    Check(p::LoadAuthorizedStorageOwner(writer,c,recipient,0,{reader,{StorageRoute::Mail,StorageCommand::Send,10000001,0,UINT32_MAX,880135}}).has_value(),"authenticated mail recipient snapshot read");
    reader.account=880334;
    Check(!p::LoadAuthorizedStorageOwner(writer,c,actor,0,{reader,{StorageRoute::Bank,StorageCommand::Withdraw}}),"SQL rejects forged character account when reading storage");
    unsigned serial=0;const auto op=[&](){auto b=std::array<std::uint8_t,16>{0x33,0x73};b[2]=static_cast<std::uint8_t>(++serial);b[3]=static_cast<std::uint8_t>(serial>>8);return b;};
    auto state=p::LoadCurrentItemOwner(writer,c,actor).value();auto sword=f::Sword(10000001);sword.owner=actor;sword.attributes.lockedSlot.reset();auto leather=f::Leather(10000002);leather.owner=actor;leather.count=20;PersistentItem coin{ItemInstanceId::Create(10000003).value(),item_catalog_fixture::CoinVoucher(),actor};coin.count=5;coin.placement=ItemPlacement{ItemStorageKind::Inventory,1,3};
    ItemCommit grant;grant.operationId=op();grant.catalogRevision=c.Revision();grant.catalogHash=c.ContentHash();grant.kind=ItemOperationKind::Grant;grant.owners={state.fence};grant.storages={state.storages[0]};const auto inventory=std::ranges::find_if(state.storages,[](auto l){return l.storage.kind==ItemStorageKind::Inventory;});grant.storages={*inventory};grant.items={{{},sword},{{},leather},{{},coin}};grant.outcomeCode=1;grant.result={1};Check(p::CommitItems(writer,c,grant).has_value(),"rich storage SQL fixture grant");
    StorageActor facts{880133,880333,880335,{120,0,0},true,true,true,true};
    const auto make=[&](StorageChoice q){std::vector<ItemOwnerFence> fences;std::vector<ItemStorageLayout> layouts;std::vector<PersistentItem> all;std::vector<ItemWallet> wallets;for(const auto o:{actor,alt,recipient,account,otherAccount,guild}){auto s=p::LoadCurrentItemOwner(writer,c,o).value();fences.push_back(s.fence);layouts.insert(layouts.end(),s.storages.begin(),s.storages.end());all.insert(all.end(),s.items.begin(),s.items.end());wallets.insert(wallets.end(),s.wallets.begin(),s.wallets.end());}const auto operation=op();std::vector<ItemInstanceId> ids;for(unsigned j=0;j<32;j++)ids.push_back(ItemInstanceId::Create(10001000+serial*32+j).value());return MakeStorageCommit(c,operation,fences,layouts,all,wallets,facts,q,ids);};
    const auto write=[&](const StoragePlan& plan){Check(p::CommitItems(writer,c,plan.commit).has_value(),"atomic shared storage SQL write");Check(p::CommitItems(writer,c,plan.commit)->replay,"shared storage operation replay");};
    auto deposit=make({StorageRoute::Bank,StorageCommand::Deposit,10000001});Check(deposit.has_value(),"SQL bank plan");write(*deposit);auto bank=p::LoadCurrentItemOwner(writer,c,account).value();Check(Find(bank,10000001).attributes==sword.attributes && Find(bank,10000001).stones==sword.stones && Find(bank,10000001).refinementLevel==9,"stored attributes sockets and level retained");
    Check(p::ClaimOwnerSession(writer,c,actor).has_value() && p::ClaimOwnerSession(writer,c,alt).has_value(),"two character relogs");Check(p::LoadCurrentItemOwner(writer,c,account)->fence.sessionGeneration==1,"character relog never claims the shared account generation");facts.pid=880134;facts.guildLeader=false;auto take=make({StorageRoute::Bank,StorageCommand::Withdraw,10000001});Check(take.has_value(),"same-account alt sees bank");write(*take);auto altState=p::LoadCurrentItemOwner(writer,c,alt).value();Check(Find(altState,10000001).id==sword.id && Find(altState,10000001).attributes==sword.attributes,"alt receives exact rich instance");write(*make({StorageRoute::Bank,StorageCommand::Deposit,10000001}));facts.pid=880133;facts.guildLeader=true;write(*make({StorageRoute::Bank,StorageCommand::Withdraw,10000001}));
    auto split=make({StorageRoute::Bank,StorageCommand::Deposit,10000002,7});Check(split && split->commit.items.size()==2,"partial bank SQL split");const auto splitId=split->commit.items[1].after.id;write(*split);Check(Find(p::LoadCurrentItemOwner(writer,c,actor).value(),10000002).count==13 && Find(p::LoadCurrentItemOwner(writer,c,account).value(),splitId.Value()).count==7,"partial units conserved across owners");write(*make({StorageRoute::Bank,StorageCommand::Withdraw,splitId.Value(),3}));
    auto rearrange=make({StorageRoute::Bank,StorageCommand::Rearrange,splitId.Value(),0,7});Check(rearrange.has_value(),"bank rearrange has character authority fence");write(*rearrange);Check(Find(p::LoadCurrentItemOwner(writer,c,account).value(),splitId.Value()).placement->anchor==7,"shared layout move persists");
    auto redeem=make({StorageRoute::Wallet,StorageCommand::Redeem,10000003,2});Check(redeem.has_value(),"account voucher plan");write(*redeem);Check(p::LoadCurrentItemOwner(writer,c,account)->wallets[0].balance==200 && Find(p::LoadCurrentItemOwner(writer,c,actor).value(),10000003).count==3,"voucher and account credit commit together");write(*make({StorageRoute::Wallet,StorageCommand::Mint,item_catalog_fixture::CoinVoucher().LocalId(),1}));Check(p::LoadCurrentItemOwner(writer,c,account)->wallets[0].balance==100 && Find(p::LoadCurrentItemOwner(writer,c,actor).value(),10000003).count==4,"wallet debit and equivalent voucher commit together");
    auto stale=make({StorageRoute::Wallet,StorageCommand::Redeem,10000003,1});facts.pid=880134;facts.guildLeader=false;write(*make({StorageRoute::Wallet,StorageCommand::Mint,item_catalog_fixture::CoinVoucher().LocalId(),1}));Check(!p::CommitItems(writer,c,stale->commit),"concurrent same-account wallet write refuses old balance");Check(Find(p::LoadCurrentItemOwner(writer,c,actor).value(),10000003).count==4 && p::LoadCurrentItemOwner(writer,c,account)->wallets[0].balance==0,"stale wallet never consumes voucher");facts.pid=880133;facts.guildLeader=true;
    auto send=make({StorageRoute::Mail,StorageCommand::Send,10000001,0,UINT32_MAX,880135});Check(send.has_value(),"mail plan");write(*send);Check(Find(p::LoadCurrentItemOwner(writer,c,recipient).value(),10000001).placement->kind==ItemStorageKind::Mail,"offline recipient mailbox holds exact item");facts.pid=880135;facts.account=880334;facts.guild=0;facts.guildMember=facts.guildLeader=false;write(*make({StorageRoute::Mail,StorageCommand::Withdraw,10000001}));Check(Find(p::LoadCurrentItemOwner(writer,c,recipient).value(),10000001).attributes==sword.attributes,"mail claim preserves attributes");
    facts={880133,880333,880335,{120,0,0},true,true,true,true};auto mallItem=sword;mallItem.id=ItemInstanceId::Create(10000004).value();mallItem.owner=account;mallItem.boundTo=account;mallItem.placement=ItemPlacement{ItemStorageKind::Mall,1,0};bank=p::LoadCurrentItemOwner(writer,c,account).value();grant.operationId=op();grant.owners={bank.fence};grant.storages={*std::ranges::find_if(bank.storages,[](auto l){return l.storage.kind==ItemStorageKind::Mall;})};grant.items={{{},mallItem}};Check(p::CommitItems(writer,c,grant).has_value(),"mall delivery provider grant");write(*make({StorageRoute::Mall,StorageCommand::Withdraw,10000004}));Check(Find(p::LoadCurrentItemOwner(writer,c,actor).value(),10000004).boundTo==actor,"mall first claim binds to claiming character");
    auto reward=leather;reward.id=ItemInstanceId::Create(10000005).value();reward.count=2;reward.placement=ItemPlacement{ItemStorageKind::PendingAward,1,0};state=p::LoadCurrentItemOwner(writer,c,actor).value();grant.operationId=op();grant.owners={state.fence};grant.storages={*std::ranges::find_if(state.storages,[](auto l){return l.storage.kind==ItemStorageKind::PendingAward;})};grant.items={{{},reward}};Check(p::CommitItems(writer,c,grant).has_value(),"pending award provider grant");write(*make({StorageRoute::Awards,StorageCommand::Withdraw,10000005}));
    auto guildDeposit=make({StorageRoute::Guild,StorageCommand::Deposit,10000002,1});Check(guildDeposit.has_value(),"leader guild SQL deposit");const auto guildId=guildDeposit->commit.items.back().after.id;write(*guildDeposit);Check(!p::CloseEmptyTypedGuild(writer,c,880335,880133),"non-empty typed guild cannot disband");facts.pid=880134;facts.guildLeader=true;auto forgedRole=make({StorageRoute::Guild,StorageCommand::Withdraw,guildId.Value()});Check(forgedRole && !p::CommitItems(writer,c,forgedRole->commit),"SQL checks actual guild master rather than a stale role flag");facts.pid=880133;write(*make({StorageRoute::Guild,StorageCommand::Withdraw,guildId.Value()}));auto late=make({StorageRoute::Guild,StorageCommand::Deposit,10000002,1});Check(late.has_value() && p::CloseEmptyTypedGuild(writer,c,880335,880133).has_value(),"empty guild closes shared deposit gate");Check(!p::CommitItems(writer,c,late->commit),"closed guild refuses a previously prepared cross-core deposit");
    auto before=p::LoadCurrentItemOwner(writer,c,actor).value();Check(p::ClaimOwnerSession(writer,c,actor).has_value(),"final shared storage relog");auto after=p::LoadCurrentItemOwner(writer,c,actor).value();Check(after.items==before.items && after.wallets==before.wallets,"all storage outcomes survive final relog");Check(p::CommitItems(writer,c,redeem->commit)->replay,"account voucher replay after fresh login is idempotent");
}
